 IFeatureLayer fl=new FeatureLayerClass();fl.FeatureClass=Workspace(S(s,"gdb")).OpenFeatureClass(S(s,"fc"));fl.Name=S(s,"name",S(s,"fc"));((IFeatureLayerDefinition)fl).DefinitionExpression=S(s,"query");IGeoFeatureLayer gl=(IGeoFeatureLayer)fl;gl.DisplayAnnotation=false;string mode=S(s,"renderer","simple");
