 public static void Run(string input,string output,string config){if(!RuntimeManager.Bind(ProductCode.Desktop))throw new Exception("Desktop bind failed");lic=new AoInitializeClass();var ls=lic.Initialize(esriLicenseProductCode.esriLicenseProductCodeAdvanced);if(ls!=esriLicenseStatus.esriLicenseCheckedOut&&ls!=esriLicenseStatus.esriLicenseAlreadyInitialized)throw new Exception("License="+ls);
 JavaScriptSerializer js=new JavaScriptSerializer();js.MaxJsonLength=Int32.MaxValue;var cfg=js.Deserialize<Dictionary<string,object>>(File.ReadAllText(config));var page=D(cfg["page"]);font=S(page,"font","SimHei");IMapDocument d=new MapDocumentClass();d.Open(input,"");IGraphicsContainer gc=(IGraphicsContainer)d.PageLayout;List<IElement> old=new List<IElement>();gc.Reset();IElement z;while((z=gc.Next())!=null)old.Add(z);foreach(IElement q in old)gc.DeleteElement(q);IPage pg=d.PageLayout.Page;pg.StretchGraphicsWithPage=false;pg.Units=esriUnits.esriCentimeters;pg.PutCustomSize(N(page,"width_cm",19),N(page,"height_cm",24));Dictionary<string,IMap> maps=new Dictionary<string,IMap>();Dictionary<string,IMapFrame> frames=new Dictionary<string,IMapFrame>();var receipts=new ArrayList();
 foreach(object raw in(ArrayList)cfg["maps"]){var mcfg=D(raw);IMap map=new MapClass();map.Name=S(mcfg,"name");foreach(object lr in(ArrayList)mcfg["layers"]){var sl=D(lr);ILayer layer=AddLayer(sl);map.AddLayer(layer);if(map.LayerCount==1){if(layer is IFeatureLayer)map.SpatialReference=((IGeoDataset)((IFeatureLayer)layer).FeatureClass).SpatialReference;else if(layer is IRasterLayer)map.SpatialReference=((IRasterProps)((IRasterLayer)layer).Raster).SpatialReference;}}
 IEnvelope ex=new EnvelopeClass();var v=(ArrayList)mcfg["extent"];ex.PutCoords(Convert.ToDouble(v[0]),Convert.ToDouble(v[1]),Convert.ToDouble(v[2]),Convert.ToDouble(v[3]));ex.SpatialReference=map.SpatialReference;IMapFrame frame=new MapFrameClass();frame.Map=map;frame.Border=null;frame.Background=null;IElement el=(IElement)frame;el.Geometry=E(N(mcfg,"x"),N(mcfg,"y"),N(mcfg,"w"),N(mcfg,"h"));Name(el,S(mcfg,"name"));gc.AddElement(el,0);frame.MapBounds=ex;((IActiveView)map).Extent=ex;maps[map.Name]=map;frames[map.Name]=frame;
 var border=new Dictionary<string,object>{{"kind","rect"},{"name",map.Name+"_frame"},{"x",N(mcfg,"x")},{"y",N(mcfg,"y")},{"w",N(mcfg,"w")},{"h",N(mcfg,"h")},{"fill","none"},{"stroke",S(mcfg,"border_color","#3A4043")},{"width",N(mcfg,"border_width",.62)}};gc.AddElement(Element(border),0);receipts.Add(new{map=map.Name,layers=map.LayerCount,extent=new[]{ex.XMin,ex.YMin,ex.XMax,ex.YMax}});}
